// PushMode values a newer herdr adds decode as they are; see Known.
type PushMode string

const (
	PushModeAuto   PushMode = "auto"
	PushModeDirect PushMode = "direct"
	PushModeRelay  PushMode = "relay"
	PushModeOff    PushMode = "off"
)

// Known reports whether v is a value the pinned schema lists.
func (v PushMode) Known() bool {
	switch v {
	case PushModeAuto, PushModeDirect, PushModeRelay, PushModeOff:
		return true
	}
	return false
}

// Reachability of a federation peer, derived from consecutive poll outcomes.
//
// Serialized onto remote [`AgentInfo`]s so a client can tell a live peer from
// one that has gone quiet. A C-like enum, so it derives `Eq`.
//
// Reachability values a newer herdr adds decode as they are; see Known.
type Reachability string

const (
	// The last poll succeeded.
	ReachabilityReachable Reachability = "reachable"
	// One or two consecutive polls have failed; last-known agents are retained.
	ReachabilityDegraded Reachability = "degraded"
	// At least [`UNREACHABLE_MISS_THRESHOLD`] consecutive polls have failed; the
	// peer is treated as offline and its agents are stamped `unknown`.
	ReachabilityUnreachable Reachability = "unreachable"
)

// Known reports whether v is a value the pinned schema lists.
func (v Reachability) Known() bool {
	switch v {
	case ReachabilityReachable, ReachabilityDegraded, ReachabilityUnreachable:
		return true
	}
	return false
}

