// How an update attempt ended.
//
// UpdateOutcome values a newer herdr adds decode as they are; see Known.
type UpdateOutcome string

const (
	// The new build serves and is installed on disk.
	UpdateOutcomeUpdated UpdateOutcome = "updated"
	// The new build serves, but the on-disk binary could not be replaced, so
	// a restart would run the previous build.
	UpdateOutcomeUpdatedDiskStale UpdateOutcome = "updated_disk_stale"
	// The new build failed its checks; one live handoff back restored the
	// previous build, which passed the same checks.
	UpdateOutcomeRolledBack UpdateOutcome = "rolled_back"
	// Nothing changed: the attempt stopped before the switch, or the switch
	// never took effect.
	UpdateOutcomeFailedNoChange UpdateOutcome = "failed_no_change"
	// The server's state could not be confirmed; nothing was killed or
	// restarted. See `message`.
	UpdateOutcomeNeedsAttention UpdateOutcome = "needs_attention"
	// `restart_later`: the build is installed on disk and takes over on the
	// next restart.
	UpdateOutcomeDownloadedRestartRequired UpdateOutcome = "downloaded_restart_required"
)

// Known reports whether v is a value the pinned schema lists.
func (v UpdateOutcome) Known() bool {
	switch v {
	case UpdateOutcomeUpdated, UpdateOutcomeUpdatedDiskStale, UpdateOutcomeRolledBack, UpdateOutcomeFailedNoChange, UpdateOutcomeNeedsAttention, UpdateOutcomeDownloadedRestartRequired:
		return true
	}
	return false
}

